<script setup lang="ts">
import { Head } from '@inertiajs/vue3';
import { Activity, HardDrive, Layers } from '@lucide/vue';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
interface UsageRow { id: number; metric: string; quantity: number; user: { name: string } | null; project: { title: string } | null; created_at: string; }
const props = defineProps<{ usageByMetric: { metric: string; total: number }[]; storage: { projectBytes: number; organizationQuotaBytes: number }; builds: { active: number; failed: number; timedOut: number; succeeded: number }; recentUsage: { data: UsageRow[]; total: number }; }>();
function formatBytes(bytes: number): string { if (bytes < 1024) return `${bytes} B`; const units = ['KB', 'MB', 'GB', 'TB']; let value = bytes / 1024; let unit = 0; while (value >= 1024 && unit < units.length - 1) { value /= 1024; unit++; } return `${value.toFixed(1)} ${units[unit]}`; }
</script>
<template>
    <Head title="Usage and builds" />
    <main class="mx-auto w-full max-w-7xl space-y-6 p-4 sm:p-6 lg:p-8"><header><p class="text-sm font-medium text-primary">Administration</p><h1 class="text-2xl font-semibold tracking-tight sm:text-3xl">Usage &amp; builds</h1><p class="text-sm text-muted-foreground">Review recorded platform usage, storage, and compilation outcomes.</p></header>
        <section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><Card><CardContent class="flex items-center justify-between p-5"><div><p class="text-sm text-muted-foreground">Project storage</p><p class="text-2xl font-semibold">{{ formatBytes(props.storage.projectBytes) }}</p></div><HardDrive class="size-5 text-primary" /></CardContent></Card><Card><CardContent class="flex items-center justify-between p-5"><div><p class="text-sm text-muted-foreground">Organization quota</p><p class="text-2xl font-semibold">{{ formatBytes(props.storage.organizationQuotaBytes) }}</p></div><Layers class="size-5 text-primary" /></CardContent></Card><Card><CardContent class="flex items-center justify-between p-5"><div><p class="text-sm text-muted-foreground">Active builds</p><p class="text-2xl font-semibold">{{ props.builds.active }}</p></div><Activity class="size-5 text-primary" /></CardContent></Card></section>
        <section class="grid gap-6 lg:grid-cols-2"><Card><CardHeader><CardTitle>Build outcomes</CardTitle><CardDescription>Compilation totals by current outcome.</CardDescription></CardHeader><CardContent class="grid grid-cols-2 gap-3"><div v-for="item in [{ label: 'Succeeded', value: props.builds.succeeded }, { label: 'Failed', value: props.builds.failed }, { label: 'Timed out', value: props.builds.timedOut }, { label: 'Active', value: props.builds.active }]" :key="item.label" class="rounded-lg border p-4"><p class="text-sm text-muted-foreground">{{ item.label }}</p><p class="mt-1 text-xl font-semibold tabular-nums">{{ item.value }}</p></div></CardContent></Card><Card><CardHeader><CardTitle>Usage by metric</CardTitle><CardDescription>Recorded quantities grouped by metric name.</CardDescription></CardHeader><CardContent><div v-if="props.usageByMetric.length" class="divide-y"><div v-for="item in props.usageByMetric" :key="item.metric" class="flex justify-between py-3 first:pt-0 last:pb-0"><span>{{ item.metric.replaceAll('_', ' ') }}</span><span class="font-medium tabular-nums">{{ item.total.toLocaleString() }}</span></div></div><p v-else class="text-sm text-muted-foreground">No usage has been recorded yet.</p></CardContent></Card></section>
        <Card><CardHeader><CardTitle>Recent usage records</CardTitle><CardDescription>{{ props.recentUsage.total }} records</CardDescription></CardHeader><CardContent><div class="divide-y rounded-lg border"><div v-for="record in props.recentUsage.data" :key="record.id" class="flex flex-wrap justify-between gap-2 p-3 text-sm"><span class="font-medium">{{ record.metric.replaceAll('_', ' ') }} <span class="font-normal text-muted-foreground">· {{ record.user?.name ?? 'Unknown account' }}<span v-if="record.project"> · {{ record.project.title }}</span></span></span><span>{{ record.quantity.toLocaleString() }} · {{ new Date(record.created_at).toLocaleString() }}</span></div><p v-if="props.recentUsage.data.length === 0" class="p-6 text-center text-sm text-muted-foreground">No usage records are available.</p></div></CardContent></Card>
    </main>
</template>
